-- Rework US and French encyclopedia entries as equipment descriptions with key specifications and researched images.
ALTER TABLE weapon_dictionary ADD COLUMN IF NOT EXISTS image_url TEXT;
UPDATE weapon_dictionary SET description='프랑스 해군조선국(현 Naval Group)이 설계한 디젤-전기 공격잠수함 계열이다. 90B형은 공기불요추진(AIP) 장치를 장착하며 533mm 어뢰 발사관 4문을 갖춘다.', specs='{"torpedoTubes":4,"torpedoCaliberMm":533,"lengthM":67.6}'::jsonb, image_url='https://topwar.ru/uploads/posts/2019-03/1552666837_agosta-90b-3.jpg', updated_at=now()::text, maker='Naval Group' WHERE id='agosta-90b';
UPDATE weapon_dictionary SET description='미국 FMC가 M113을 바탕으로 개발한 궤도형 보병전투차량이다. 보병 수송과 화력 지원을 맡으며, 운용국별 포탑과 무장 구성이 다르다.', specs='{"crew":3,"passengers":7}'::jsonb, image_url=NULL, updated_at=now()::text, maker='FMC Corporation' WHERE id='aifv';
UPDATE weapon_dictionary SET description='프랑스 GIAT(현 KNDS France)가 개발한 수륙양용 궤도형 보병전투차량이다. 20mm 기관포와 7.62mm 동축기관총을 장착하고, 승무원 3명과 보병 8명을 수송한다.', specs='{"caliber":"20mm","crew":3,"passengers":8,"speedKmh":65,"waterSpeedKmh":7}'::jsonb, image_url='https://upload.wikimedia.org/wikipedia/commons/2/2e/AMX-10P_in_the_Mus%C3%A9e_des_Blind%C3%A9s%2C_France%2C_pic-1.JPG', updated_at=now()::text, maker='KNDS France (구 GIAT Industries)' WHERE id='amx-10p';
UPDATE weapon_dictionary SET description='프랑스 GIAT가 AMX-13 경전차 차체를 바탕으로 제작한 155mm 궤도형 자주포다. 포를 차체 뒤쪽에 노출 장착하고, 사격 때는 후방 지지삽을 내려 반동을 지탱한다.', specs='{"caliber":"155mm","crew":2}'::jsonb, image_url='https://tank-afv.com/coldwar/France/photos/AMX_MK_F3-155_Fuerza%20-Argentina.jpg', updated_at=now()::text, maker='GIAT Industries' WHERE id='amx-mk-f3';
UPDATE weapon_dictionary SET description='미국 보잉이 개발한 HMMWV 탑재 단거리 방공체계다. 회전식 포탑 양쪽 발사 포드에 스팅어 미사일 4발씩, 총 8발을 탑재하고 12.7mm 기관총을 함께 장착한다.', specs='{"missileCount":8,"armament":"FIM-92 스팅어 8발, 12.7mm 기관총"}'::jsonb, image_url='https://www.joint-forces.com/wp-content/uploads/2019/07/05-SG19-1-0193.jpg', updated_at=now()::text, maker='Boeing' WHERE id='avenger';
UPDATE weapon_dictionary SET description='프랑스 KNDS France가 생산하는 차륜형 자주포다. 155mm/52구경장포를 탑재하며, 6×6 및 8×8 차체와 탄종에 따라 운용 성능이 달라진다.', specs='{"caliber":"155mm/52","rangeKm":40,"crew":5,"lengthM":10}'::jsonb, image_url='https://knds.com/media/Photo_CAESAR_5_23ba8924e7.jpg', updated_at=now()::text, maker='KNDS France' WHERE id='caesar';
UPDATE weapon_dictionary SET description='미국 Fincantieri Marinette Marine이 건조하는 미 해군 유도미사일 호위함 설계다. 대공·대잠·대함 임무를 수행하도록 설계됐으며, 57mm 함포와 Mk 41 수직발사관 32셀을 갖춘다.', specs='{"caliber":"57mm","vlsCells":32,"lengthM":151}'::jsonb, image_url='https://d1ldvf68ux039x.cloudfront.net/thumbs/photos/2104/6600683/2000w_q95.jpg', updated_at=now()::text, maker='Fincantieri Marinette Marine' WHERE id='constellation-class-ffg';
UPDATE weapon_dictionary SET description='프랑스 Naval Group이 설계·건조하는 다목적 호위함이다. 전장 약 122m, 배수량 약 4,500t이며 76mm 함포, 엑조세 대함미사일 8발과 32셀 수직발사체계를 갖춘다.', specs='{"lengthM":122,"displacementT":4500,"caliber":"76mm","vlsCells":32}'::jsonb, image_url='https://www.naval-group.com/sites/default/files/styles/social_networks_share/public/2025-01/navalgroup_amiralronarch_BD-7_0.jpg?h=102d18d1&itok=hoY8AINr', updated_at=now()::text, maker='Naval Group' WHERE id='fdi-class';
UPDATE weapon_dictionary SET description='프랑스 Naval Group과 이탈리아 Fincantieri가 공동 설계·건조한 다목적 호위함 계열이다. 대잠·대공·대함 임무별 파생형이 있으며 프랑스형은 전장 약 142m, 배수량 약 6,000t급이다.', specs='{"lengthM":142,"displacementT":6000,"speedKt":27}'::jsonb, image_url='https://www.globalsecurity.org/military/world/europe/images/fremm-aquitaine-image-04.jpg', updated_at=now()::text, maker='Naval Group, Fincantieri' WHERE id='fremm';
UPDATE weapon_dictionary SET description='프랑스 Naval Group이 설계·건조한 아랍에미리트 해군 Gowind 2500급 초계전투함이다. 전장 약 102m, 배수량 약 2,800t이며 76mm 함포, 엑조세 대함미사일과 VL MICA 대공미사일을 탑재한다.', specs='{"lengthM":102,"displacementT":2800,"speedKt":25.5,"caliber":"76mm"}'::jsonb, image_url='https://www.defence21.com/sites/default/files/styles/crop_image_style_3_2/public/2023-02/Gowind%202500%20UAE_0.jpeg?h=baecfb85&itok=ZUAybR_R', updated_at=now()::text, maker='Naval Group' WHERE id='gowind-2500';
UPDATE weapon_dictionary SET description='미국 Avondale Shipyards가 건조한 해안경비대 고내구성 경비함 계열이다. 전장 약 115m의 장거리 순찰함으로, 함미 비행갑판에서 헬기를 운용할 수 있다.', specs='{"lengthM":115,"speedKt":29,"displacementT":3250}'::jsonb, image_url='https://www.globalsecurity.org/military/systems/ship/images/whec-715-Hamilton3.jpg', updated_at=now()::text, maker='Avondale Shipyards', type_ko='고내구성 경비함' WHERE id='hamilton-class';
UPDATE weapon_dictionary SET description='프랑스와 이탈리아가 공동 개발한 방공 호위함 계열이다. Aster 15·30 미사일과 다기능 레이더를 중심으로 함대 방공을 맡으며, 프랑스형과 이탈리아형의 무장 구성이 다르다.', specs='{"lengthM":153,"displacementT":7050,"speedKt":29}'::jsonb, image_url='https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/French_destroyer_Forbin_%28D620%29_underway_in_the_Arabian_Sea_on_31_May_2009_%28090531-N-9988F-406%29.jpg/1280px-French_destroyer_Forbin_%28D620%29_underway_in_the_Arabian_Sea_on_31_May_2009_%28090531-N-9988F-406%29.jpg', updated_at=now()::text, maker='Horizon SAS' WHERE id='horizon';
UPDATE weapon_dictionary SET description='프랑스 Naval Group이 설계·건조한 스텔스 호위함이다. 전장 약 125m, 배수량 약 3,600t이며 엑조세 대함미사일과 100mm 함포를 탑재한다.', specs='{"lengthM":125,"displacementT":3600,"speedKt":25,"caliber":"100mm"}'::jsonb, image_url='https://www.defense.gouv.fr/sites/default/files/styles/16_9_md/public/marine/2022_MTLN_031_A_010_003.jpg?h=b8c0c725&itok=N1n6rZ9Y', updated_at=now()::text, maker='Naval Group (구 DCNS)' WHERE id='la-fayette';
UPDATE weapon_dictionary SET description='General Dynamics Land Systems가 개발한 8×8 차륜형 장갑차 계열이다. 보병수송·정찰·지휘·화력지원형으로 구성되며, 임무에 따라 30mm 또는 40mm 기관포와 105mm 포탑을 장착한다.', specs='{"wheels":8,"speedKmh":110,"rangeKm":1000,"payloadKg":11000}'::jsonb, image_url='https://international.gdls.com/spanish/images/products/LAV-700-icon.jpg', updated_at=now()::text, maker='General Dynamics Land Systems' WHERE id='lav-700';
UPDATE weapon_dictionary SET description='프랑스 육군이 운용하는 M270 계열 궤도형 다연장로켓 발사체계다. 227mm 로켓 포드 2개를 탑재해 유도 로켓 12발 또는 전술미사일 2발을 발사한다.', specs='{"caliber":"227mm","pods":2,"rocketsPerPod":6,"missilesPerPod":1}'::jsonb, image_url='https://www.defense.gouv.fr/sites/default/files/styles/16_9_md/public/terre/lance-roquette-unitaire.jpg?itok=WUhywM71', updated_at=now()::text, maker='KNDS France, Lockheed Martin' WHERE id='lru-france';
UPDATE weapon_dictionary SET description='미국에서 개발된 궤도형 155mm 자주포 계열이며, 현재형 M109A7은 BAE Systems가 생산한다. 포탑에 155mm 곡사포를 탑재하고 장갑차 부대에 기동 화력을 제공한다.', specs='{"caliber":"155mm","crew":4}'::jsonb, image_url='https://api.army.mil/e2/c/images/2023/04/04/3312d47c/original.jpg', updated_at=now()::text, maker='BAE Systems' WHERE id='m109';
UPDATE weapon_dictionary SET description='미국 FMC가 제작한 궤도형 중자주포다. 203mm 곡사포 1문을 탑재하며, 사격 때 후방 지지삽을 내려 차체를 고정한다.', specs='{"caliber":"203mm","crew":5}'::jsonb, image_url='https://cdn10.picryl.com/photo/1975/12/17/an-m-110-203mm-self-propelled-howitzer-is-parked-on-the-flight-line-prior-being-8e13ff-1024.jpg', updated_at=now()::text, maker='FMC Corporation' WHERE id='m110';
UPDATE weapon_dictionary SET description='미국 FMC가 개발한 궤도형 병력수송장갑차다. 기본형은 승무원 2명과 보병 11명을 수송하며, 차체 상부에 12.7mm 기관총을 장착할 수 있다.', specs='{"crew":2,"passengers":11,"armament":"12.7mm 기관총"}'::jsonb, image_url='https://cdn10.picryl.com/photo/2004/10/01/us-army-1st-battalion-4th-cavalry-regiment-1st-infantry-division-armored-vehicles-eccba8-1600.jpg', updated_at=now()::text, maker='FMC Corporation' WHERE id='m113';
UPDATE weapon_dictionary SET description='미국 록히드 마틴이 생산하는 차륜형 고기동 다연장로켓 체계다. 발사 포드 1개에 GMLRS 로켓 6발 또는 ATACMS·PrSM 미사일 1발을 탑재한다.', specs='{"caliber":"227mm","pods":1,"rocketsPerPod":6,"missilesPerPod":1,"crew":3}'::jsonb, image_url='https://d1ldvf68ux039x.cloudfront.net/thumbs/photos/2311/8099051/2000w_q95.jpg', updated_at=now()::text, maker='Lockheed Martin' WHERE id='m142-himars';
UPDATE weapon_dictionary SET description='미국 BAE Systems가 생산하는 궤도형 보병전투차량이다. 25mm 기관포, 7.62mm 동축기관총과 TOW 대전차미사일 발사기를 장착하며, 승무원 3명과 보병 6명을 수송한다.', specs='{"caliber":"25mm","missileCount":2,"crew":3,"passengers":6}'::jsonb, image_url='https://d1ldvf68ux039x.cloudfront.net/thumbs/photos/2502/8886826/1000w_q95.jpg', updated_at=now()::text, maker='BAE Systems' WHERE id='m2-bradley';
UPDATE weapon_dictionary SET description='미국산 궤도형 다연장로켓 체계로 Lockheed Martin과 BAE Systems가 생산한다. 6발들이 발사 포드 2개를 장착해 GMLRS 로켓 12발 또는 전술미사일 2발을 발사한다.', specs='{"caliber":"227mm","pods":2,"rocketsPerPod":6,"missilesPerPod":1,"crew":3}'::jsonb, image_url='https://api.army.mil/e2/c/images/2024/12/17/560bcf79/original.jpg', updated_at=now()::text, maker='Lockheed Martin, BAE Systems' WHERE id='m270-mlrs';
UPDATE weapon_dictionary SET description='M2 Bradley의 개량형으로, 미국 BAE Systems가 생산한다. 25mm 기관포와 TOW 대전차미사일 발사기를 유지하면서 전자장비·전력계통·방호력을 개선했다.', specs='{"caliber":"25mm","missileCount":2,"crew":3,"passengers":6}'::jsonb, image_url='https://d1ldvf68ux039x.cloudfront.net/thumbs/photos/2502/8886826/1000w_q95.jpg', updated_at=now()::text, maker='BAE Systems' WHERE id='m2a4-bradley';
UPDATE weapon_dictionary SET description='미국 레이시온이 개발한 중거리 지대공 미사일 체계다. 반능동 레이더 유도로 항공기와 순항미사일을 요격하며, 발사대 한 기에 MIM-23 미사일 3발을 탑재한다.', specs='{"missilesPerLauncher":3,"rangeKm":40}'::jsonb, image_url='https://cdn10.picryl.com/photo/1973/05/01/us-army-soldiers-load-mim-23b-hawk-missiles-onto-a-towed-launcher-24f4e6-1600.jpg', updated_at=now()::text, maker='Raytheon' WHERE id='mim-23-hawk';
UPDATE weapon_dictionary SET description='프랑스 MBDA가 생산하는 휴대형 단거리 지대공 미사일이다. 적외선 탐색기로 표적을 추적하며, 약 3kg 탄두와 최대 약 7.5km의 교전거리를 갖는다.', specs='{"rangeKm":7.5,"warheadKg":3,"propulsion":"고체연료 로켓"}'::jsonb, image_url='https://www.defense.gouv.fr/sites/default/files/terre/mistral.jpg', updated_at=now()::text, maker='MBDA France' WHERE id='mistral';
UPDATE weapon_dictionary SET description='미국 록히드 마틴이 설계하고 Fincantieri Marinette Marine이 건조한 다목적 수상전투함이다. 연안전투함 설계를 바탕으로 57mm 함포, 하푼 대함미사일과 SeaRAM 근접방어체계를 탑재한다.', specs='{"caliber":"57mm","antiShipMissiles":8,"armament":"57mm 함포, 하푼, SeaRAM"}'::jsonb, image_url='https://www.lockheedmartin.com/content/dam/lockheed-martin/mde/ksa-mmsc.jpg', updated_at=now()::text, maker='Lockheed Martin, Fincantieri Marinette Marine' WHERE id='mmsc';
UPDATE weapon_dictionary SET description='미국에서 건조된 올리버 해저드 페리급 유도미사일 호위함이다. 대잠·대공·대함 임무를 맡으며 76mm 함포와 함재 헬기를 운용한다.', specs='{"caliber":"76mm","lengthM":138,"speedKt":29}'::jsonb, image_url=NULL, updated_at=now()::text, maker='Bath Iron Works' WHERE id='oliver-hazard-perry-class';
UPDATE weapon_dictionary SET description='미국 레이시온의 레이더 유도 방공체계로, PAC-2·PAC-3 계열 요격미사일을 운용한다. 발사대 적재량은 미사일 형식에 따라 PAC-2 4발 또는 PAC-3 MSE 최대 16발이다.', specs='{"armament":"PAC-2 4발 또는 PAC-3 MSE 최대 16발/발사대"}'::jsonb, image_url='https://d1ldvf68ux039x.cloudfront.net/thumbs/photos/2105/6651803/2000w_q95.jpg', updated_at=now()::text, maker='Raytheon, Lockheed Martin' WHERE id='patriot';
UPDATE weapon_dictionary SET description='프랑스와 이탈리아의 Eurosam이 개발한 이동식 지대공 미사일 체계다. Aster 30 미사일과 다기능 레이더를 사용하며, 발사대 한 기에 미사일 8발을 탑재한다.', specs='{"missilesPerLauncher":8,"armament":"Aster 30","rangeKm":100}'::jsonb, image_url='https://www.defense.gouv.fr/sites/default/files/air/2026_ORION_AD_012_041.jpg', updated_at=now()::text, maker='Eurosam (MBDA, Thales)' WHERE id='samp-t';
UPDATE weapon_dictionary SET description='프랑스 Naval Group이 설계한 디젤-전기 공격잠수함이다. 533mm 어뢰 발사관 6문을 갖추며, 어뢰·기뢰·대함미사일을 임무에 맞춰 탑재한다.', specs='{"torpedoTubes":6,"torpedoCaliberMm":533,"weaponsLoad":18}'::jsonb, image_url='https://www.infodefensa.com/images/showid2/4591123?mh=700&w=900', updated_at=now()::text, maker='Naval Group' WHERE id='scorpene-class';
UPDATE weapon_dictionary SET description='미국 General Dynamics Land Systems가 생산하는 8×8 차륜형 장갑차 계열이다. 기본 보병수송형은 승무원 2명과 보병 9명을 태우며, 정찰·박격포·화력지원 등 여러 파생형이 있다.', specs='{"wheels":8,"crew":2,"passengers":9,"speedKmh":100}'::jsonb, image_url='https://d1ldvf68ux039x.cloudfront.net/thumbs/photos/2603/9569087/1000w_q95.jpg', updated_at=now()::text, maker='General Dynamics Land Systems' WHERE id='stryker';
UPDATE weapon_dictionary SET description='프랑스 KNDS France와 Arquus가 개발한 8×8 보병전투차량이다. 25mm 기관포 포탑형은 승무원 2명과 보병 8명을 수송하며, 지휘·정찰 등 파생형도 있다.', specs='{"wheels":8,"caliber":"25mm","crew":2,"passengers":8}'::jsonb, image_url='https://www.defense.gouv.fr/sites/default/files/dga/2015_tmtz_219_000_014.jpg', updated_at=now()::text, maker='KNDS France, Arquus' WHERE id='vbci';
UPDATE weapon_dictionary SET description='프랑스 MBDA가 개발한 이동식 단거리 지대공 미사일 체계다. 적외선 탐색기 또는 능동 레이더 탐색기를 갖춘 MICA 미사일을 사용하며, 지상형은 전방위 수직발사 방식으로 운용한다.', specs='{"rangeKm":20,"armament":"MICA RF 또는 MICA IR"}'::jsonb, image_url='https://www.mbda-systems.com/sites/mbda/files/styles/c_editorial__sm/public/2024-08/MBDA_0169456_WEB.jpg?itok=1AZUckzV', updated_at=now()::text, maker='MBDA France' WHERE id='vl-mica';
INSERT INTO schema_migrations(version,applied_at) VALUES (14,now()::text) ON CONFLICT (version) DO NOTHING;
UPDATE metadata SET value=(CAST(value AS INTEGER)+1)::text WHERE key='revision';
